// The auth schema against better-auth's own model of the configured auth
// (spec 329): `getAuthTables(options)` is what better-auth's schema generator
// reads, so every model and field it expects must exist in the database built
// from the journal alone, with a compatible type and nullability. The schema is
// hand-written and generated by drizzle-kit, never by better-auth; this test is
// what keeps the two in step on every later change.
import type { PGlite } from '@electric-sql/pglite';
import { getAuthTables } from 'better-auth/db';
import { getTableColumns, getTableName, type Table } from 'drizzle-orm';
import { afterAll, beforeAll, describe, expect, it } from 'vitest';

import { createAuth } from '../../src/index';
import * as schema from '../../src/schema';
import { drizzleFor, migrate, setAuthEnv } from '../helpers/auth-db';

type ModelField = { type: unknown; required?: boolean; fieldName?: string; references?: unknown };
type Model = { modelName: string; fields: Record<string, ModelField> };
type DbColumn = { table_name: string; column_name: string; data_type: string; is_nullable: string };

/** Postgres types that store each better-auth field type. */
const COMPATIBLE: Record<string, string[]> = {
  string: ['text'],
  number: ['integer', 'bigint'],
  boolean: ['boolean'],
  date: ['timestamp with time zone'],
};

/**
 * Documented deviations, each deliberate. `apikey.referenceId` is a uuid with a
 * foreign key to `auth.users` (on delete cascade), where the plugin's model says
 * a plain string with no reference: the plugin only ever writes a user id there,
 * every user id is a uuid (`generateId: 'uuid'`), and the foreign key deletes a
 * service user's keys with it.
 */
const DEVIATIONS: Record<string, string> = { 'apikey.referenceId': 'uuid' };

const isTable = (value: unknown): value is Table =>
  typeof value === 'object' && value !== null && Symbol.for('drizzle:Name') in value;

/** The drizzle table for a model: by export name, as the drizzle adapter finds it (`rateLimit`), else by SQL name. */
function tableFor(modelName: string): Table | undefined {
  const byKey = (schema as Record<string, unknown>)[modelName];
  if (isTable(byKey)) return byKey;
  return Object.values(schema).filter(isTable).find((t) => getTableName(t) === modelName);
}

/** Every mismatch between better-auth's model and the database's columns. */
async function modelProblems(client: PGlite, models: Record<string, Model>): Promise<string[]> {
  const { rows } = await client.query<DbColumn>(
    `SELECT table_name, column_name, data_type, is_nullable FROM information_schema.columns WHERE table_schema = 'auth'`
  );
  const problems: string[] = [];
  for (const model of Object.values(models)) {
    const table = tableFor(model.modelName);
    if (!table) {
      problems.push(`${model.modelName}: no drizzle table`);
      continue;
    }
    const columns = getTableColumns(table) as Record<string, { name: string }>;
    for (const [field, def] of Object.entries(model.fields)) {
      const key = def.fieldName ?? field;
      const column = columns[key] ?? columns[field];
      const dbColumn = column && rows.find((r) => r.table_name === getTableName(table) && r.column_name === column.name);
      if (!dbColumn) {
        problems.push(`${model.modelName}.${field}: missing in the database`);
        continue;
      }
      // Ids are uuids here (generateId: 'uuid'), so a field referencing another model is a uuid too.
      const allowed = def.references
        ? ['uuid']
        : DEVIATIONS[`${model.modelName}.${field}`]
          ? [DEVIATIONS[`${model.modelName}.${field}`]!]
          : (COMPATIBLE[String(def.type)] ?? []);
      if (!allowed.includes(dbColumn.data_type)) {
        problems.push(`${model.modelName}.${field}: ${dbColumn.data_type}, expected ${allowed.join(' or ')}`);
      }
      if (def.required === true && dbColumn.is_nullable !== 'NO') {
        problems.push(`${model.modelName}.${field}: required but nullable`);
      }
    }
  }
  return problems;
}

let client: PGlite;
let models: Record<string, Model>;

beforeAll(async () => {
  client = await migrate();
  setAuthEnv('http://localhost:3100');
  models = getAuthTables(createAuth(drizzleFor(client)).options as never) as unknown as Record<string, Model>;
});

afterAll(async () => {
  await client?.close();
});

describe("the auth schema matches better-auth's own model of the configured auth", () => {
  it('covers the models this config uses, including apikey (spec 329)', () => {
    const names = Object.values(models).map((m) => m.modelName);
    for (const name of ['users', 'session', 'account', 'verification', 'jwks', 'apikey']) expect(names).toContain(name);
    expect(Object.keys(models.apikey!.fields)).toHaveLength(21);
  });

  it('every model and field better-auth expects exists, with a compatible type and nullability', async () => {
    expect(await modelProblems(client, models)).toEqual([]);
  });

  it('has no phone-number field anywhere (spec 329 §5, owner amendment 2)', () => {
    for (const model of Object.values(models)) {
      for (const field of Object.keys(model.fields)) expect(field.toLowerCase()).not.toContain('phone');
    }
  });

  it('fails when the database drifts (negative control)', async () => {
    const drifted = await migrate();
    try {
      await drifted.exec(`ALTER TABLE auth.apikey DROP COLUMN "key"; ALTER TABLE auth.apikey ALTER COLUMN "name" TYPE integer USING NULL`);
      const problems = await modelProblems(drifted, models);
      expect(problems).toContain('apikey.key: missing in the database');
      expect(problems).toContain('apikey.name: integer, expected text');
    } finally {
      await drifted.close();
    }
  });
});
